"use client";

import { useAnimate, useReducedMotion } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a one-time code field. Pass `value` to control it, or `defaultValue` to let it hold its own digits. */
export type OtpFieldProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue" | "children"> & {
  /** The accessible name of the group of boxes. */
  label?: string;
  /** How many digits the code has. */
  length?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /**
   * Runs once every box holds a digit. Return `false`, or a promise of
   * `false`, when the code is wrong: the row shakes once and clears.
   */
  onComplete?: (code: string) => void | boolean | Promise<void | boolean>;
  /** Shown under the boxes after a wrong code. */
  errorMessage?: string;
  disabled?: boolean;
};

const SHAKE = { x: [0, -6, 6, -4, 4, 0] };
const SHAKE_TIMING = { duration: 0.35, ease: "easeOut" } as const;

const digitsOf = (text: string) => text.replace(/\D/g, "");

/**
 * A one-time code field with one box per digit. Typing moves to the next box,
 * Backspace moves back, and a paste fills every box. A wrong code shakes the
 * row once, clears it and says why in words.
 */
export function OtpField({
  label = "Verification code",
  length = 6,
  value,
  defaultValue = "",
  onValueChange,
  onComplete,
  errorMessage = "That code did not match. Try again.",
  disabled = false,
  className,
  ...divProps
}: OtpFieldProps) {
  const [ownValue, setOwnValue] = useState(() => digitsOf(defaultValue).slice(0, length));
  const [rejected, setRejected] = useState(false);
  const boxesRef = useRef<(HTMLInputElement | null)[]>([]);
  const [rowRef, animate] = useAnimate<HTMLDivElement>();
  const reduceMotion = useReducedMotion();
  const errorId = useId();
  const code = digitsOf(value ?? ownValue).slice(0, length);

  const focusBox = (index: number) => boxesRef.current[Math.max(0, Math.min(length - 1, index))]?.focus();

  const commit = (next: string) => {
    if (value === undefined) setOwnValue(next);
    if (next !== code) onValueChange?.(next);
  };

  const reject = () => {
    setRejected(true);
    commit("");
    focusBox(0);
    if (!reduceMotion && rowRef.current) void animate(rowRef.current, SHAKE, SHAKE_TIMING);
  };

  const update = (next: string, focusAt: number) => {
    const clean = next.slice(0, length);
    setRejected(false);
    commit(clean);
    focusBox(focusAt);
    if (clean.length < length || clean === code) return;
    // A rejected promise is the caller's own failure, so it is left to surface.
    void Promise.resolve(onComplete?.(clean)).then((accepted) => {
      if (accepted === false) reject();
    });
  };

  const removeAt = (index: number) => update(code.slice(0, index) + code.slice(index + 1), index);

  const handleChange = (index: number, raw: string) => {
    const current = code[index] ?? "";
    if (raw === "" && current) return removeAt(index);
    let typed = digitsOf(raw);
    // A key pressed in a filled box arrives as the old digit plus the new one.
    if (current && typed.length === 2) typed = typed.replace(current, "");
    if (!typed) return;
    // The code has no gaps: a digit typed past the end lands in the first empty box.
    const at = Math.min(index, code.length);
    const next = typed.length >= length ? typed : code.slice(0, at) + typed + code.slice(at + typed.length);
    update(next, at + typed.length);
  };

  const handleKeyDown = (index: number, event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
      event.preventDefault();
      focusBox(index + (event.key === "ArrowLeft" ? -1 : 1));
      return;
    }
    if (event.key !== "Backspace") return;
    event.preventDefault();
    // An empty box hands Backspace to the box before it.
    const at = code[index] ? index : index - 1;
    if (at >= 0) removeAt(at);
  };

  return (
    <div
      {...divProps}
      role="group"
      aria-label={label}
      aria-describedby={rejected ? errorId : undefined}
      className={cn("flex max-w-full flex-col items-center gap-2", className)}
    >
      <div ref={rowRef} className="flex max-w-full items-center gap-1 sm:gap-2">
        {Array.from({ length }, (_, index) => (
          <input
            key={`box-${index + 1}`}
            ref={(box) => {
              boxesRef.current[index] = box;
            }}
            value={code[index] ?? ""}
            aria-label={`Digit ${index + 1} of ${length}`}
            aria-invalid={rejected || undefined}
            inputMode="numeric"
            autoComplete="one-time-code"
            spellCheck={false}
            disabled={disabled}
            onChange={(event) => handleChange(index, event.target.value)}
            onKeyDown={(event) => handleKeyDown(index, event)}
            // Selected on focus, so a new digit replaces the old one.
            onFocus={(event) => event.target.select()}
            onPaste={(event) => {
              event.preventDefault();
              const pasted = digitsOf(event.clipboardData.getData("text"));
              if (pasted) update(pasted, pasted.length);
            }}
            className={cn(
              "aspect-square w-11 min-w-0 rounded-xl border bg-background text-center text-lg font-medium text-foreground tabular-nums caret-transparent outline-none",
              "motion-safe:transition-colors motion-safe:duration-150",
              "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
              "disabled:cursor-not-allowed disabled:opacity-50",
              rejected ? "border-destructive" : code[index] ? "border-foreground/40" : "border-border",
            )}
          />
        ))}
      </div>
      <p id={errorId} role="alert" className="min-h-5 text-center text-sm text-destructive">
        {rejected ? errorMessage : ""}
      </p>
    </div>
  );
}
